  'report.title': 'Configurações de relatórios', 'report.subtitle': 'Diagnósticos locais privados e consentimento',
  'report.automatic': 'Relatórios de diagnóstico automáticos',
  'report.destination': 'Os relatórios de diagnóstico são enviados para https://gamja.top/api/gamja-bot/reports quando o serviço verificado está disponível. O envio fica indisponível nesta compilação quando o receptor não está configurado.',
  'report.contents': 'Os relatórios contêm a versão do aplicativo e da compilação, sistema operacional e arquitetura, horário, componente, etapa, código de erro fixo, número de ocorrências e até 16 transições fixas. Uma falha com diagnóstico higienizado também inclui um ID de correlação, motivo e classe de exceção fixos, quadros de pilha relativos ao aplicativo, IDs de contexto limitados, status HTTP e um ID de solicitação do provedor validado. Eles não contêm chats, instruções de agentes, texto do provedor, chaves, URLs, caminhos da pasta pessoal, saída de processos, área de transferência, conteúdo do navegador, capturas de tela, logs brutos nem corpos de solicitações ou respostas. Uma descrição manual opcional é separada e exibida antes do envio.',
  'report.retention': 'Os relatórios locais não enviados expiram após 7 dias. Os relatórios aceitos são mantidos pelo receptor por 30 dias. É necessário publicar um aviso de privacidade e definir um procedimento de acesso para operadores antes de ativar o envio ao vivo.',
  'report.consent': 'Esta escolha se aplica a esta instalação no seu perfil de usuário do sistema operacional durante esta sessão do aplicativo. Ela abrange apenas novas falhas após a ativação. Depois de reiniciar o aplicativo, os relatórios automáticos começam desativados; ative-os novamente para essa sessão. Desativar interrompe futuras tentativas automáticas e remove os relatórios automáticos não enviados. Um relatório já recebido não pode ser recuperado por este controle.',
  'report.autoSend': 'Enviar erros de diagnóstico automaticamente', 'report.loading': 'Carregando configurações locais de relatórios…',
  'report.unavailable': 'Envio indisponível. A adesão automática ficará disponível quando o receptor verificado estiver configurado.',
