  'problem.privacy': 'Somente os campos mostrados na visualização completa do relatório são enviados. As falhas selecionadas podem incluir um ID de correlação, motivo e classe de exceção fixos, quadros de pilha relativos ao aplicativo, IDs de contexto limitados, status HTTP e um ID de solicitação do provedor validado. Não são coletados chats, chaves, capturas de tela, logs brutos, caminhos locais, corpos de solicitações ou respostas nem arquivos. O texto que você digitar pode conter informações pessoais.',
