  "localModels.history.search": "Buscar registros de funções",
  "localModels.history.searchScope": "Busca apenas modelo, endereço local, número, estado e horários de observação/teste registrados neste histórico recebido. Não deduz horários de solicitação ausentes nem busca o corpo dos relatórios. Trocar páginas ou filtros mantém os relatórios abertos; consultar não executa verificações nem altera funções disponíveis.",
  "localModels.previous.title": "Configurações locais anteriores",
  "localModels.previous.scope": "Mostra apenas tentativas e relatórios mantidos nesta sessão. A configuração anterior mais recente e as tentativas pendentes ou incertas continuam visíveis. O filtro de estado do arquivo é o resultado de salvar a conexão, não o teste de funções. Ler um relatório antigo não restaura entradas, cria conexões, executa verificações nem altera funções disponíveis.",
