  "readiness.browse.historyFindScope": "Busca apenas até 20 registros recebidos desta conexão: ID, modelo, resultado, horário, duração e configuração de referência. Exibe cinco por página na ordem recebida. Busca e filtros não carregam mais histórico nem executam testes; registros fora da lista recebida não são buscados.",
